{
  "root": "main_stack",
  "state": {
    "itineraryDays": [
      {
        "dayTitle": "Day 1: The Golden Temple & Northern Zen",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/Kinkakuji_2010-02-14.jpg/1200px-Kinkakuji_2009-02-14.jpg",
        "imageAlt": "Kinkaku-ji (Golden Pavilion)",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/camera.svg",
        "activities": "Kinkaku-ji: Capture the reflection of the gold leaf against red maples. Best lighting: 09:00 AM.\nRyoan-ji: Minimalist rock garden photography with autumn framing. Best lighting: 11:30 AM.\nEnko-ji: Famous for the \"framed\" view of the garden from the temple interior. Best lighting: 03:30 PM.",
        "actionLabel": "View Map",
        "actionUrl": "https://www.google.com/maps/search/temples+northern+kyoto"
      },
      {
        "dayTitle": "Day 2: Arashiyama Riverside & Bamboo",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/Arashiyama_Bamboo_Grove_Kyoto.jpg/1200px-Arashiyama_Bamboo_Grove_Kyoto.jpg",
        "imageAlt": "Arashiyama Bamboo Grove",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/tree.svg",
        "activities": "Arashiyama Bamboo Grove: Soft, filtered light through the stalks. Best lighting: 07:00 AM (to avoid crowds).\nTenryu-ji Garden: Stunning pond reflections of the Sogenchi Garden. Best lighting: 09:30 AM.\nOkochi Sanso Villa: Panoramic views of the city and gorge from the tea house. Best lighting: 02:00 PM.",
        "actionLabel": "Arashiyama Guide",
        "actionUrl": "https://www.insidekyoto.com/arashiyama-district"
      },
      {
        "dayTitle": "Day 3: The Philosophers Path & Illuminations",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/ab/Eikando_Zenrinji_Kyoto05n.jpg/1200px-Eikando_Zenrinji_Kyoto05n.jpg",
        "imageAlt": "Eikan-do Zenrin-ji",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/moon-stars.svg",
        "activities": "Nanzen-ji: Large brick aqueduct set against fiery maples. Best lighting: 10:00 AM.\nEikan-do: Widely considered the best foliage spot in Kyoto. Best lighting: 03:00 PM.\nKodai-ji Night Illumination: Capturing the high-contrast light shows on the trees. Best lighting: 06:00 PM.",
        "actionLabel": "Check Illuminations",
        "actionUrl": "https://www.kyototourism.org/en/column/13444/"
      },
      {
        "dayTitle": "Day 4: Southern Kyoto & Hidden Valleys",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0e/Tofuku-ji_Tsuten-kyo_01.jpg/1200px-Tofuku-ji_Tsuten-kyo_01.jpg",
        "imageAlt": "Tofuku-ji Tsuten-kyo Bridge",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/geo-alt.svg",
        "activities": "Tofuku-ji: The view from Tsuten-kyo Bridge is iconic for autumn. Best lighting: 08:30 AM (Opening).\nFushimi Inari: Capture the orange torii gates against the forest. Best lighting: 03:00 PM (Lower crowds).\nBishamon-do: Famous for the \"red carpet\" of fallen maple leaves on the steps. Best lighting: 04:30 PM.",
        "actionLabel": "Tofuku-ji Tickets",
        "actionUrl": "https://www.tofukuji.jp/english/"
      },
      {
        "dayTitle": "Day 5: Higashiyama Heritage",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a2/Kiyomizu-dera_in_Kyoto-r.jpg/1200px-Kiyomizu-dera_in_Kyoto-r.jpg",
        "imageAlt": "Kiyomizu-dera",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/building.svg",
        "activities": "Kiyomizu-dera: The wooden stage surrounded by a \"sea\" of red. Best lighting: 06:30 AM (Sunrise).\nSannenzaka/Ninenzaka: Traditional streets for architectural photography. Best lighting: 08:00 AM.\nChion-in Sanmon Gate: Grand scale photography with autumn accents. Best lighting: 04:00 PM.",
        "actionLabel": "Photography Tips",
        "actionUrl": "https://www.japan-guide.com/e/e2158.html"
      }
    ],
    "diningOptions": [
      {
        "name": "Shigetsu",
        "location": "Arashiyama",
        "description": "Located inside Tenryu-ji Temple. Authentic Shojin Ryori (Buddhist vegan) served in a stunning garden setting."
      },
      {
        "name": "Towzen",
        "location": "Sakyo-ku",
        "description": "Famous for Vegan Ramen. The broth is creamy soy-milk based, completely free of animal or fish products."
      },
      {
        "name": "Mumokuteki Cafe",
        "location": "Central",
        "description": "A trendy plant-based cafe that avoids all seafood and dashi. Great for lunch near the shopping arcades."
      },
      {
        "name": "Ain Soph Journey",
        "location": "Kawaramachi",
        "description": "A fully vegan restaurant specializing in \"Heavenly Pancakes\" and savory meals with no fish stock."
      },
      {
        "name": "Veg Out",
        "location": "Near Kyoto Station",
        "description": "Riverside vegan cafe offering macrobiotic bowls and sandwiches, ideal for a safe, seafood-free breakfast or lunch."
      }
    ],
    "costBreakdown": [
      {
        "expenseCategory": "Transport",
        "estimatedCostUSD": "$25",
        "estimatedCostJPY": "¥3,700",
        "details": "Mix of Subway and 2-3 Taxi hops"
      },
      {
        "expenseCategory": "Food & Drink",
        "estimatedCostUSD": "$90",
        "estimatedCostJPY": "¥13,500",
        "details": "High-end Shojin Ryori + Snacks"
      },
      {
        "expenseCategory": "Entrance Fees",
        "estimatedCostUSD": "$35",
        "estimatedCostJPY": "¥5,200",
        "details": "3-4 Temples + Special Illumination"
      },
      {
        "expenseCategory": "Gear/Misc",
        "estimatedCostUSD": "$50",
        "estimatedCostJPY": "¥7,600",
        "details": "Camera accessories or souvenirs"
      },
      {
        "expenseCategory": "Total",
        "estimatedCostUSD": "$200",
        "estimatedCostJPY": "¥30,000",
        "details": "Daily solo allocation"
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "lg",
        "padding": 16
      },
      "children": [
        "title",
        "intro_text",
        "itinerary_table",
        "dining_heading",
        "dining_intro",
        "tea_ceremony_card",
        "safe_dining_heading",
        "dining_options_table",
        "budget_heading",
        "budget_intro",
        "financial_overview_text",
        "primary_strategy_text",
        "cost_breakdown_table",
        "quick_actions_heading",
        "quick_actions_stack",
        "sources_heading",
        "sources_stack"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "November Photography Itinerary: Peak Autumn Colors",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This itinerary focuses on capturing Kyoto's vibrant maples during the peak \"Koyo\" season. To avoid crowds and capture the best light, early starts are essential."
      },
      "children": []
    },
    "itinerary_table": {
      "type": "Table",
      "props": {
        "statePath": "/itineraryDays",
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "dayTitle",
        "columns": [
          {
            "key": "dayTitle",
            "label": "Day"
          },
          {
            "key": "image",
            "label": "Image"
          },
          {
            "key": "imageAlt",
            "label": "Image Alt"
          },
          {
            "key": "icon",
            "label": "Icon"
          },
          {
            "key": "activities",
            "label": "Activities"
          },
          {
            "key": "actionLabel",
            "label": "Action"
          },
          {
            "key": "actionUrl",
            "label": "URL"
          }
        ]
      },
      "children": []
    },
    "dining_heading": {
      "type": "Text",
      "props": {
        "text": "Gion Tea Culture & Seafood-Free Dining",
        "variant": "h2"
      },
      "children": []
    },
    "dining_intro": {
      "type": "Text",
      "props": {
        "text": "In Japan, \"Dashi\" (fish stock) is ubiquitous. To ensure a strict no-seafood/no-dashi diet, these recommendations focus on Shojin Ryori (Buddhist vegan cuisine) and dedicated vegan restaurants."
      },
      "children": []
    },
    "tea_ceremony_card": {
      "type": "Card",
      "props": {},
      "children": [
        "tea_ceremony_title_stack",
        "tea_ceremony_description",
        "tea_ceremony_button"
      ]
    },
    "tea_ceremony_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "tea_ceremony_icon",
        "tea_ceremony_title"
      ]
    },
    "tea_ceremony_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/cup-hot.svg"
      },
      "children": []
    },
    "tea_ceremony_title": {
      "type": "Text",
      "props": {
        "text": "Authentic Tea Ceremony: Camellia Flower Teahouse",
        "variant": "h3"
      },
      "children": []
    },
    "tea_ceremony_description": {
      "type": "Text",
      "props": {
        "text": "Located in a quiet lane in Gion, Camellia provides a professional, English-guided ceremony. You will learn the history of Zen and tea while whisking your own matcha."
      },
      "children": []
    },
    "tea_ceremony_button": {
      "type": "Button",
      "props": {
        "label": "Book Camellia"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.tea-kyoto.com/"
          }
        }
      },
      "children": []
    },
    "safe_dining_heading": {
      "type": "Text",
      "props": {
        "text": "Safe Dining Options (No Seafood/No Dashi)",
        "variant": "h3"
      },
      "children": []
    },
    "dining_options_table": {
      "type": "Table",
      "props": {
        "statePath": "/diningOptions",
        "domain": "generic",
        "preferredPresentation": "cards",
        "primaryColumn": "name",
        "columns": [
          {
            "key": "name",
            "label": "Restaurant"
          },
          {
            "key": "location",
            "label": "Location"
          },
          {
            "key": "description",
            "label": "Description"
          }
        ]
      },
      "children": []
    },
    "budget_heading": {
      "type": "Text",
      "props": {
        "text": "Daily Photography Budget Breakdown",
        "variant": "h2"
      },
      "children": []
    },
    "budget_intro": {
      "type": "Text",
      "props": {
        "text": "With a $200 USD (approx. ¥30,000 JPY) daily budget, you can afford high-end meals and comfortable local transit."
      },
      "children": []
    },
    "financial_overview_text": {
      "type": "Text",
      "props": {
        "text": "Total Daily Budget: $200.00"
      },
      "children": []
    },
    "primary_strategy_text": {
      "type": "Text",
      "props": {
        "text": "Primary Strategy: High-quality lunch/dinner and taxi use for gear transport."
      },
      "children": []
    },
    "cost_breakdown_table": {
      "type": "Table",
      "props": {
        "statePath": "/costBreakdown",
        "domain": "generic",
        "preferredPresentation": "table",
        "numericColumns": [
          "estimatedCostUSD",
          "estimatedCostJPY"
        ],
        "columns": [
          {
            "key": "expenseCategory",
            "label": "Expense Category"
          },
          {
            "key": "estimatedCostUSD",
            "label": "Estimated Cost (USD)"
          },
          {
            "key": "estimatedCostJPY",
            "label": "Estimated Cost (JPY)"
          },
          {
            "key": "details",
            "label": "Details"
          }
        ]
      },
      "children": []
    },
    "quick_actions_heading": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "kyoto_weather_button",
        "vegan_guide_button"
      ]
    },
    "kyoto_weather_button": {
      "type": "Button",
      "props": {
        "label": "Kyoto Weather"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.accuweather.com/en/jp/kyoto-shi/224436/weather-forecast/224436"
          }
        }
      },
      "children": []
    },
    "vegan_guide_button": {
      "type": "Button",
      "props": {
        "label": "Vegan Guide Kyoto"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.happycow.net/asia/japan/kyoto/"
          }
        }
      },
      "children": []
    },
    "sources_heading": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "kyoto_tourism_button",
        "japan_guide_button",
        "happycow_button"
      ]
    },
    "kyoto_tourism_button": {
      "type": "Button",
      "props": {
        "label": "Kyoto City Tourism Association"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.kyototourism.org/en/"
          }
        }
      },
      "children": []
    },
    "japan_guide_button": {
      "type": "Button",
      "props": {
        "label": "Japan Guide Autumn Colors"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.japan-guide.com/e/e2014.html"
          }
        }
      },
      "children": []
    },
    "happycow_button": {
      "type": "Button",
      "props": {
        "label": "HappyCow Vegan Directory"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.happycow.net/"
          }
        }
      },
      "children": []
    }
  }
}
